import { useEffect, useMemo, useState } from 'react';
import { errorMessage } from '../../lib/session';
import type { MemberProfile } from '../../lib/session';
import {
  DEFAULT_SORT,
  EYEBROW,
  SEARCH_PLACEHOLDER,
  SUBTITLE,
  TITLE,
  fetchSentOffers,
  filterSentOffers,
  resultCountLabel,
  sortSentOffers,
  type SentOffer,
  type SortColumn,
} from '../../lib/sent-offers';
import { SentOffersTable } from './SentOffersTable';
import styles from './SentOffers.module.css';

/**
 * VND-01 · Mis Ofertas (vista del vendedor).
 *
 * La pantalla posee todo el estado: ofertas, carga, error, texto de búsqueda y
 * ordenación. La carga se hace exactamente una vez al montar; `orgId` no cambia
 * durante la vida de la pantalla, así que incluirlo en las dependencias solo
 * provocaría un refetch.
 */
export function SentOffers({
  profile,
  onOpenThread,
}: {
  profile: MemberProfile;
  onOpenThread?: (threadId: string) => void;
}) {
  const [offers, setOffers] = useState<SentOffer[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);
  const [query, setQuery] = useState('');
  const [sort, setSort] = useState(DEFAULT_SORT);

  useEffect(() => {
    let cancelled = false;

    fetchSentOffers(profile.orgId)
      .then((data) => {
        if (cancelled) return;
        setOffers(data);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err : new Error(String(err)));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const filtered = useMemo(() => filterSentOffers(offers, query), [offers, query]);
  const sorted = useMemo(
    () => sortSentOffers(filtered, sort.column, sort.direction),
    [filtered, sort],
  );

  const handleSort = (column: SortColumn) => {
    setSort((prev) =>
      prev.column === column
        ? { column, direction: prev.direction === 'asc' ? 'desc' : 'asc' }
        : { column, direction: 'asc' },
    );
  };

  const handleOpenThread = (threadId: string) => {
    onOpenThread?.(threadId);
  };

  const hasQuery = query.trim().length > 0;

  return (
    <div
      className={styles.content}
      data-testid="selling-body"
      aria-busy={loading ? 'true' : 'false'}
    >
      <p className={styles.eyebrow}>{EYEBROW}</p>
      <h1 className={styles.title}>{TITLE}</h1>
      <p className={styles.subtitle}>{SUBTITLE}</p>

      {loading && <p className={styles.loading}>Cargando ofertas…</p>}

      {!loading && error && (
        <div className={styles.alert} role="alert">
          {errorMessage(error)}
        </div>
      )}

      {!loading && !error && (
        <>
          <div className={styles.searchBar}>
            <div className={styles.searchWrap}>
              <svg
                className={styles.searchIcon}
                aria-hidden="true"
                width="15"
                height="15"
                viewBox="0 0 16 16"
                fill="none"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinecap="round"
              >
                <circle cx="7" cy="7" r="5" />
                <path d="M11 11l3.5 3.5" />
              </svg>
              <input
                type="text"
                className={styles.searchInput}
                placeholder={SEARCH_PLACEHOLDER}
                value={query}
                onChange={(event) => setQuery(event.target.value)}
              />
              {query.length > 0 && (
                <button
                  type="button"
                  className={styles.searchClear}
                  aria-label="Limpiar búsqueda"
                  onClick={() => setQuery('')}
                >
                  ×
                </button>
              )}
            </div>
            <span className={styles.resultCount}>{resultCountLabel(filtered.length)}</span>
          </div>

          <SentOffersTable
            offers={sorted}
            sort={sort}
            onSort={handleSort}
            onOpenThread={handleOpenThread}
            hasQuery={hasQuery}
          />
        </>
      )}
    </div>
  );
}

/* El mock usa fondo blanco para la tarjeta de tabla; no hay token de blanco
   puro en §1.4, así que --bw-surface-mist (#F8F9FB) es la superficie clara
   más próxima. */
.tableOuter {
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: var(--bw-radius);
  overflow: auto;
}

.table {
  width: 100%;
  border-collapse: collapse;
}

.th {
  padding: 9px 14px;
  text-align: left;
  font-size: var(--bw-size-label);
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--bw-text-secondary);
  background: var(--bw-surface-mist);
  border-bottom: 1px solid var(--bw-line-steel);
  white-space: nowrap;
  position: sticky;
  top: 0;
  z-index: 1;
  user-select: none;
}

.sortButton {
  font: inherit;
  text-transform: inherit;
  letter-spacing: inherit;
  background: none;
  border: none;
  padding: 0;
  margin: 0;
  color: inherit;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  cursor: pointer;
}

.sortButton:hover {
  color: var(--bw-ink-steel);
}

.sortIcon {
  font-style: normal;
  font-size: var(--bw-size-hint);
  color: var(--bw-hint-steel);
}

.sortAsc .sortIcon,
.sortDesc .sortIcon {
  color: var(--bw-calibration-blue);
}

.td {
  padding: 10px 14px;
  font-size: var(--bw-size-input);
  color: var(--bw-ink-steel);
  border-bottom: 1px solid var(--bw-divider-mist);
  vertical-align: middle;
  white-space: nowrap;
}

tbody tr:last-child .td {
  border-bottom: none;
}

.row:hover .td {
  background: var(--bw-row-hover-tint);
}

.ref {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-label);
  font-weight: 500;
  color: var(--bw-deep-steel);
}

.brand {
  display: block;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  color: var(--bw-input-placeholder);
  margin-top: 1px;
}

.org {
  font-size: var(--bw-size-label);
  font-weight: 500;
  color: var(--bw-ink-steel);
}

.ts {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  color: var(--bw-input-placeholder);
}

.statusPending {
  display: inline-block;
  padding: 2px 7px;
  border-radius: var(--bw-radius);
  font-size: var(--bw-size-hint);
  letter-spacing: var(--bw-ls-hint);
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border: 1px solid var(--bw-badge-warning-border);
}

.statusAccepted {
  display: inline-block;
  padding: 2px 7px;
  border-radius: var(--bw-radius);
  font-size: var(--bw-size-hint);
  letter-spacing: var(--bw-ls-hint);
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border: 1px solid var(--bw-badge-success-border);
}

.statusRejected {
  display: inline-block;
  padding: 2px 7px;
  border-radius: var(--bw-radius);
  font-size: var(--bw-size-hint);
  letter-spacing: var(--bw-ls-hint);
  background: var(--bw-sensitive-bg);
  color: var(--bw-sensitive-text);
  border: 1px solid var(--bw-badge-danger-border);
}

.statusSuperseded {
  display: inline-block;
  padding: 2px 7px;
  border-radius: var(--bw-radius);
  font-size: var(--bw-size-hint);
  letter-spacing: var(--bw-ls-hint);
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-ink-steel-soft);
  border: 1px solid var(--bw-badge-neutral-border);
}

.actionButton {
  height: 26px;
  padding: 0 10px;
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-label);
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.12s;
}

.actionPrimary {
  height: 26px;
  padding: 0 10px;
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-label);
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.12s;
  background: var(--bw-calibration-blue);
  /* No hay token de blanco puro; --bw-on-dark-hover es blanco al 90%. */
  color: var(--bw-on-dark-hover);
  border: none;
}

.actionPrimary:hover {
  opacity: 0.87;
}

.actionGhost {
  height: 26px;
  padding: 0 10px;
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-label);
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.12s;
  background: none;
  color: var(--bw-text-secondary);
  border: 1px solid var(--bw-line-steel-strong);
}

.actionGhost:hover {
  border-color: var(--bw-hover-border);
  color: var(--bw-ink-steel);
}

.emptyCell {
  padding: 48px 20px;
  text-align: center;
  font-size: var(--bw-size-input);
  color: var(--bw-input-placeholder);
}

import type { OfferState } from '../../lib/offers';
import {
  EMPTY_NO_MATCHES,
  EMPTY_NO_OFFERS,
  rowActionLabel,
  sentAtLabel,
  type SentOffer,
  type SortColumn,
  type SortDirection,
} from '../../lib/sent-offers';
import styles from './SentOffersTable.module.css';

interface SentOffersTableProps {
  offers: SentOffer[];
  sort: { column: SortColumn; direction: SortDirection };
  onSort: (column: SortColumn) => void;
  onOpenThread: (threadId: string) => void;
  hasQuery: boolean;
}

/** Las cuatro columnas ordenables de la §5.4. `Acciones` no lo es. */
const SORTABLE_COLUMNS: { key: SortColumn; label: string }[] = [
  { key: 'referencia', label: 'Referencia' },
  { key: 'organizacion', label: 'Organización' },
  { key: 'estado', label: 'Estado' },
  { key: 'fecha', label: 'Fecha' },
];

/**
 * Los cuatro estados del CHECK `thread_items_estado_oferta_chk` (0003), cada uno
 * con su tono. El Record está tipado contra `OfferState`: si el esquema ganara
 * un quinto estado, TS obliga a decidir su clase en vez de dejar la celda sin
 * adorno o con el tono de otro.
 */
const STATE_CLASS: Record<OfferState, string> = {
  Pendiente: styles.statusPending,
  Aceptada: styles.statusAccepted,
  Rechazada: styles.statusRejected,
  'Superada por contraoferta': styles.statusSuperseded,
};

/**
 * Tabla de VND-01 · Mis Ofertas.
 *
 * Presentacional: recibe las filas ya filtradas y ya ordenadas y no vuelve a
 * tocarlas. El estado vacío vive aquí y no en la pantalla — "no hay filas" es
 * un estado de la lista, igual que en SRCH-01 y MSG-01.
 */
export function SentOffersTable({
  offers,
  sort,
  onSort,
  onOpenThread,
  hasQuery,
}: SentOffersTableProps) {
  return (
    <div className={styles.tableOuter}>
      <table className={styles.table}>
        <thead>
          <tr>
            {SORTABLE_COLUMNS.map((column) => {
              const isActive = sort.column === column.key;
              const thClass = isActive
                ? `${styles.th} ${sort.direction === 'asc' ? styles.sortAsc : styles.sortDesc}`
                : styles.th;
              return (
                <th
                  key={column.key}
                  scope="col"
                  className={thClass}
                  aria-sort={
                    isActive
                      ? sort.direction === 'asc'
                        ? 'ascending'
                        : 'descending'
                      : 'none'
                  }
                >
                  <button
                    type="button"
                    className={styles.sortButton}
                    onClick={() => onSort(column.key)}
                  >
                    {column.label}
                    <span className={styles.sortIcon} aria-hidden="true">
                      {isActive ? (sort.direction === 'asc' ? '↑' : '↓') : '↕'}
                    </span>
                  </button>
                </th>
              );
            })}
            <th scope="col" className={styles.th}>
              Acciones
            </th>
          </tr>
        </thead>
        <tbody>
          {offers.length === 0 ? (
            <tr>
              <td colSpan={5} className={`${styles.td} ${styles.emptyCell}`}>
                {hasQuery ? EMPTY_NO_MATCHES : EMPTY_NO_OFFERS}
              </td>
            </tr>
          ) : (
            offers.map((offer) => (
              <tr
                key={offer.id}
                className={styles.row}
                data-testid="sent-offer-row"
                data-offer-id={offer.id}
              >
                <td className={styles.td}>
                  <span className={styles.ref}>{offer.partNumber ?? '—'}</span>
                  {offer.brand && <span className={styles.brand}>{offer.brand}</span>}
                </td>
                <td className={styles.td}>
                  <span className={styles.org}>{offer.counterpartyName}</span>
                </td>
                <td className={styles.td}>
                  <span className={STATE_CLASS[offer.state]}>{offer.state}</span>
                </td>
                <td className={styles.td}>
                  <span className={styles.ts}>{sentAtLabel(offer.createdAt)}</span>
                </td>
                <td className={styles.td}>
                  <button
                    type="button"
                    className={offer.state === 'Aceptada' ? styles.actionPrimary : styles.actionGhost}
                    onClick={() => onOpenThread(offer.threadId)}
                  >
                    {rowActionLabel(offer.state)}
                  </button>
                </td>
              </tr>
            ))
          )}
        </tbody>
      </table>
    </div>
  );
}
